import {newOnce,validatePack} from './collections.js';
import {PLANTS,LEGACY_PLANTS} from './farm.js';
import {sprite as originalSprite} from './pixels.js';
export function installUpgrades(api){
const $=id=>document.getElementById(id),s=()=>api.getState(),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;},btn=(text,fn,cls='quiet')=>{const b=el('button',text,cls);b.type='button';b.onclick=fn;return b;};
function changed(){api.favoritesChanged?.();api.save();api.renderAll();}
function renderShortcuts(){const options=$('historyOptions');options.replaceChildren();const names=api.historyNames(s());names.slice(-30).reverse().forEach(n=>{const o=document.createElement('option');o.value=n;options.append(o);});$('shortcuts').replaceChildren();if(s().favorites.length){$('shortcuts').append(el('small','常用事項 · 點一下新增到當日'));const chips=el('div');s().favorites.forEach(name=>chips.append(btn('＋ '+name,()=>{const task=newOnce(name,api.currentDay(),api.uid());if(api.addTask)api.addTask(task);else s().tasks.push(task);changed();},'favoriteChip')));$('shortcuts').append(chips);}
const manager=$('nameManager');manager.replaceChildren();const all=[...new Set([...s().favorites,...names])];if(!all.length)manager.append(el('p','使用過的待辦名稱會記在這裡。','muted'));all.slice(-40).reverse().forEach(name=>{const row=el('div',undefined,'nameRow');row.append(el('span',name));const favorite=s().favorites.includes(name);row.append(btn(favorite?'★':'☆',()=>{s().favorites=favorite?s().favorites.filter(n=>n!==name):[...s().favorites,name];changed();}));if(favorite)row.append(btn('改名',()=>{const v=prompt('修改常用按鈕名稱（不更動歷史紀錄）',name);if(!v?.trim())return;s().favorites=[...new Set(s().favorites.map(n=>n===name?v.trim():n))];changed();}));row.append(btn('移除',()=>{s().favorites=s().favorites.filter(n=>n!==name);s().hiddenNames=[...new Set([...s().hiddenNames,name])];changed();}));manager.append(row);});}
function renderShelf(){const slots=$('shelfSlots');slots.replaceChildren();s().shelf.forEach((item,i)=>{const b=el('button',undefined,'shelfSlot');if(item){let p=api.plantFor(item.index);if(item.pot!==null&&!p.images)p={...p,pot:item.pot};const img=el('img');img.src=api.sprite(p,4,p.variant);img.alt=p.name;b.append(img,el('small',p.short||p.name));b.setAttribute('aria-label','布置第 '+(i+1)+' 格：'+p.name);}else{b.append(el('span','＋','emptySlot'),el('small','放一盆小植物'));b.setAttribute('aria-label','布置第 '+(i+1)+' 格');}b.onclick=()=>openShelfPicker(i);slots.append(b);});}
function openShelfPicker(slot=null,index=null){if(slot===null){const free=s().shelf.findIndex(x=>x===null);slot=free>=0?free:0;}const dialog=$('shelfDialog');$('shelfTitle').textContent='窗台第 '+(slot+1)+' 格';$('shelfActions').replaceChildren();const item=s().shelf[slot];if(item){$('shelfActions').append(btn('收回收藏',()=>{s().shelf[slot]=null;changed();dialog.close();}));for(const [label,delta] of [['← 往前',-1],['往後 →',1]]){const to=slot+delta;if(to>=0&&to<6)$('shelfActions').append(btn(label,()=>{[s().shelf[slot],s().shelf[to]]=[s().shelf[to],s().shelf[slot]];changed();openShelfPicker(to);}));}const p=api.plantFor(item.index);if(!p.images){$('shelfActions').append(el('small','盆器：'));['暖陶','青瓷','玫瑰'].forEach((label,pot)=>$('shelfActions').append(btn(label,()=>{item.pot=pot;changed();openShelfPicker(slot);},'potChoice '+((item.pot??p.pot)===pot?'chosen':''))));}}
const choices=$('shelfChoices');choices.replaceChildren();const g=api.growth(api.total(s()));const ids=s().claimed.filter(i=>i<g.completed);if(!ids.length)choices.append(el('p','先收穫一盆植物，就能布置窗台。','emptyMessage'));ids.slice(-120).forEach(i=>{const p=api.plantFor(i),b=el('button',undefined,'pot'),img=el('img');img.src=api.sprite(p,4,p.variant);img.alt=p.name;b.append(img,el('b',p.name),el('small',i===index?'剛選的這一盆':'點一下放到此格'));if(s().shelf.some(x=>x?.index===i))b.append(el('small','已在窗台'));b.onclick=()=>{s().shelf=s().shelf.map(x=>x?.index===i?null:x);s().shelf[slot]={index:i,pot:null};changed();dialog.close();};choices.append(b);});if(!dialog.open)dialog.showModal();}
$('closeShelf').onclick=()=>$('shelfDialog').close();$('shelfDialog').addEventListener('click',e=>{if(e.target===$('shelfDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
let draftImages=Array(5).fill(null),draftFruit=null,editing=null;
function message(text){$('packMessage').textContent=text;}
function showDraft(){const list=$('stageUploads');list.replaceChildren();['種子','嫩芽','葉叢','花苞','成熟','收穫物（選填）'].forEach((name,i)=>{const label=el('label',undefined,'uploadStage'),title=el('span',name),im=el('img');im.src=(i===5?draftFruit:draftImages[i])||api.sprite(PLANTS[0],Math.min(i,5));im.alt=name+'預覽';if(!(i===5?draftFruit:draftImages[i]))im.className='placeholder';const file=el('input');file.type='file';file.accept='image/png,image/jpeg,image/gif,image/webp';file.setAttribute('aria-label','上傳'+name+'圖片');file.onchange=async()=>{const f=file.files[0];if(!f)return;if(f.size>250000||!['image/png','image/jpeg','image/gif','image/webp'].includes(f.type)){message('請使用 250 KB 以下的 PNG / JPEG / GIF / WebP。');file.value='';return;}const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});try{await new Promise((resolve,reject)=>{const test=new Image();test.onload=resolve;test.onerror=reject;test.src=data;});if(i===5)draftFruit=data;else draftImages[i]=data;showDraft();message(name+'圖片已加入表單，按儲存後才會套用。');}catch{message('這張圖片無法讀取，請換一張。');}};label.append(title,im,file);list.append(label);});}
function clearDraft(){editing=null;draftImages=Array(5).fill(null);draftFruit=null;$('cropName').value='';$('cropGoal').value='15';showDraft();}
function chooseNext(key){if(key.startsWith('builtin:')){const i=Number(key.split(':')[1]);s().builtinSettings[i]={...(s().builtinSettings[i]||{}),enabled:true};}s().nextCropKey=key;api.save();message('已選好下一盆；目前這盆成熟後會接著養。');renderCrops();}
function renderCrops(){const list=$('cropList');list.replaceChildren();const title=el('h3','內建作物');list.append(title);PLANTS.forEach((p,i)=>{const setting=s().builtinSettings[i]||{},row=el('div',undefined,'cropRow'),label=el('label'),check=el('input');check.type='checkbox';check.checked=setting.enabled!==false;check.setAttribute('aria-label','啟用 '+p.name);check.onchange=()=>{s().builtinSettings[i]={...setting,enabled:check.checked};api.save();message('培養清單已更新，現有盆栽會保留。');renderCrops();};label.append(check,el('span',p.name));const goal=el('input');goal.type='number';goal.min=1;goal.max=240;goal.value=setting.goal??p.goal;goal.setAttribute('aria-label',p.name+'培養分鐘');goal.onchange=()=>{const n=Number(goal.value);if(!Number.isFinite(n)||n<1||n>240){goal.value=setting.goal??p.goal;return;}s().builtinSettings[i]={...setting,goal:n};api.save();message('新培養時間會從之後的盆栽開始套用。');};row.append(label,goal,el('small','分鐘'),btn(s().nextCropKey==='builtin:'+i?'下一盆 ✓':'接著養',()=>chooseNext('builtin:'+i)));list.append(row);});list.append(el('h3','自訂作物'));if(!s().cropDefs.length)list.append(el('p','可以匯入作物包，或在下方上傳五張生長圖片。','muted'));s().cropDefs.forEach(p=>{const row=el('div',undefined,'cropRow'),im=el('img');im.src=s().cropAssets[p.assetKey][4];im.alt=p.name;row.append(im,el('span',p.name+' · '+p.goal+' 分鐘'),btn(s().nextCropKey===p.assetKey?'下一盆 ✓':'接著養',()=>chooseNext(p.assetKey)),btn('編輯',()=>{editing=p.assetKey;draftImages=[...s().cropAssets[p.assetKey]];draftFruit=s().cropFruits?.[p.assetKey]||null;$('cropName').value=p.name;$('cropGoal').value=p.goal;document.querySelector('.cropEditor').open=true;showDraft();$('cropName').focus();}),btn('移除',()=>{if(!confirm('停止之後培養「'+p.name+'」？已收藏的植物會保留。'))return;s().cropDefs=s().cropDefs.filter(x=>x.assetKey!==p.assetKey);if(s().nextCropKey===p.assetKey)s().nextCropKey=null;api.save();renderCrops();message('已移除培養項目，收藏與正在生長的植物仍保留。');}));list.append(row);});}
function addCrops(plants){for(const p of plants){const key=api.uid();s().cropAssets[key]=p.images;s().cropFruits??={};if(p.fruit)s().cropFruits[key]=p.fruit;s().cropDefs.push({name:p.name,short:p.short,goal:p.goal,assetKey:key,enabled:true});}}
function download(name,data){const a=el('a');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('cropForm').onsubmit=e=>{e.preventDefault();try{const p=validatePack({version:1,plants:[{name:$('cropName').value,goal:Number($('cropGoal').value),images:draftImages,fruit:draftFruit||undefined}]})[0];if(!editing&&s().cropDefs.length>=12)throw Error('最多啟用 12 種自訂作物。');const oldDefs=[...s().cropDefs],oldAssets={...s().cropAssets};if(editing)s().cropDefs=s().cropDefs.filter(p=>p.assetKey!==editing);addCrops([p]);if(!api.save()){s().cropDefs=oldDefs;s().cropAssets=oldAssets;throw Error('儲存空間不足，請使用較小的圖片。');}clearDraft();renderCrops();message('作物已儲存；按「接著養」可指定下一盆。');}catch(err){message(err.message);}};
$('clearCrop').onclick=clearDraft;
$('importPack').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>3000000)throw Error('作物包請小於 3 MB。');const plants=validatePack(JSON.parse(await f.text()));await Promise.all(plants.flatMap(p=>p.images.map(src=>new Promise((resolve,reject)=>{const im=new Image();im.onload=resolve;im.onerror=()=>reject(Error('作物包中有無法讀取的圖片。'));im.src=src;}))));if(s().cropDefs.length+plants.length>12)throw Error('最多啟用 12 種自訂作物，請先移除不需要的項目。');const oldDefs=[...s().cropDefs],oldAssets={...s().cropAssets};addCrops(plants);if(!api.save()){s().cropDefs=oldDefs;s().cropAssets=oldAssets;throw Error('儲存空間不足，請縮小圖片後再匯入。');}renderCrops();message('已匯入 '+plants.length+' 種作物，可以選「接著養」。');}catch(err){message('未匯入：'+err.message);}e.target.value='';};
$('exportPack').onclick=()=>{if(!s().cropDefs.length){message('尚未新增自訂作物，可以先下載範例包。');return;}download('時光小苗-自訂作物包.json',{version:1,plants:s().cropDefs.map(p=>({name:p.name,goal:p.goal,images:s().cropAssets[p.assetKey],fruit:s().cropFruits?.[p.assetKey]}))});};
async function uri(src){if(src.startsWith('data:'))return src;const blob=await (await fetch(src)).blob();return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});}
$('examplePack').onclick=()=>download('時光小苗-原創範例作物包.json',{version:1,plants:[{name:'範例金盞花',goal:10,images:[0,1,2,3,4].map(stage=>originalSprite(LEGACY_PLANTS[0],stage)),fruit:originalSprite(LEGACY_PLANTS[0],4)}]});
$('backupDemo').onclick=()=>download('日日手帳-蘑菇紀錄.json',{type:'little-harvest-backup',version:1,data:s()});
$('restoreDemo').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>12000000)throw Error('備份過大');const raw=JSON.parse(await f.text()),d=raw.data;if(raw.type!=='little-harvest-backup'||raw.version!==1||d.version!==1||!Array.isArray(d.tasks)||!Array.isArray(d.sessions)||!Array.isArray(d.claimed)||!Array.isArray(d.cropQueue)||!d.cropQueue.length||d.tasks.some(t=>typeof t.text!=='string'||!Array.isArray(t.done))||d.sessions.some(x=>!Number.isFinite(x.seconds)||x.seconds<0)||d.cropQueue.some(p=>!Number.isFinite(p.goal)||p.goal<1||p.goal>240)||!Array.isArray(d.shelf)||d.shelf.length!==6||!Array.isArray(d.favorites)||!Array.isArray(d.cropDefs))throw Error('備份格式不符');for(const images of Object.values(d.cropAssets||{}))validatePack({version:1,plants:[{name:'驗證',goal:15,images}]});if(!confirm('匯入會取代目前的蘑菇計時與收成紀錄，不會更動手帳待辦或筆記。確定匯入？'))return;api.replaceState(d);changed();renderCrops();message('已匯入蘑菇紀錄。');}catch(err){message('未還原：'+err.message);}e.target.value='';};
renderCrops();showDraft();return{renderShortcuts,renderShelf,openShelfPicker,renderCrops};
}
